import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.CFuv5BrO.js";const k=JSON.parse('{"title":"D3.1 · Device agentd and visibility","description":"Hearth D3.1 development increment: Users can see a trusted desktop come online, its capabilities, and whether it can currently run GUI tasks.","frontmatter":{"title":"D3.1 · Device agentd and visibility","description":"Hearth D3.1 development increment: Users can see a trusted desktop come online, its capabilities, and whether it can currently run GUI tasks.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-3/d3-1.md","filePath":"en/delivery/stage-3/d3-1.md","lastUpdated":null}'),n={name:"en/delivery/stage-3/d3-1.md"};function r(o,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[s(`<p class="eyebrow">STAGE 3 · D3.1 · 1 / 4</p><h1 id="d3-1-·-device-agentd-and-visibility" tabindex="-1">D3.1 · Device agentd and visibility <a class="header-anchor" href="#d3-1-·-device-agentd-and-visibility" aria-label="Permalink to &quot;D3.1 · Device agentd and visibility&quot;">​</a></h1><p class="lead">Turn a desktop into an identifiable, authorizable, revocable execution node before discussing GUI actions.</p><p class="page-meta">STAGE 3 · D3.1 · 1 vertical increment · 4 work packages</p><div class="section-grid"><div><strong>User-visible outcome</strong>Users can see a trusted desktop come online, its capabilities, and whether it can currently run GUI tasks.</div><div><strong>Completion gate</strong>A device registers, is visible, and can be revoked; mismatched tasks are not assigned; offline devices have explicit state; agentd cannot exceed declared capability.</div></div><h2 id="what-this-increment-solves" tabindex="-1">What this increment solves <a class="header-anchor" href="#what-this-increment-solves" aria-label="Permalink to &quot;What this increment solves&quot;">​</a></h2><p>Users can see a trusted desktop come online, its capabilities, and whether it can currently run GUI tasks.</p><p>Stage 3 follows observation, takeover, low-risk action, and high-risk action; desktop automation that cannot be observed or taken over is not product-ready.</p><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><ul><li>Stage 1–2 recovery, approval, idempotency, receipts, and browser isolation are stable.</li><li>A dedicated desktop device can pair and has explicit allowed windows, applications, and file scopes.</li><li>GUI tasks run in an isolated desktop and users can pause and take over at any time.</li></ul><h2 id="four-implementation-work-packages" tabindex="-1">Four implementation work packages <a class="header-anchor" href="#four-implementation-work-packages" aria-label="Permalink to &quot;Four implementation work packages&quot;">​</a></h2><blockquote><p>Every work package must produce runnable code, a reproducible check, or a concrete UI result; interfaces alone or pages alone do not count as complete.</p></blockquote><h3 id="_01-·-device-pairing-and-durable-identity" tabindex="-1">01 · Device pairing and durable identity <a class="header-anchor" href="#_01-·-device-pairing-and-durable-identity" aria-label="Permalink to &quot;01 · Device pairing and durable identity&quot;">​</a></h3><p>The user confirms pairing with a one-time short code or QR; the device generates and stores a key pair while the server stores only public key, device ID, and trust state. Pairing sessions expire and are single-use, and the device page shows last confirmation, agentd version, and trust source.</p><h3 id="_02-·-capability-declaration-and-least-privilege" tabindex="-1">02 · Capability declaration and least privilege <a class="header-anchor" href="#_02-·-capability-declaration-and-least-privilege" aria-label="Permalink to &quot;02 · Capability declaration and least privilege&quot;">​</a></h3><p>At registration, agentd declares observable windows, operable applications, allowed file roots, input capabilities, and disabled sensitive capabilities. Validate signatures and versions; every task request must match item by item. Reject assignment and name the missing capability instead of silently degrading.</p><h3 id="_03-·-online-state-and-device-details" tabindex="-1">03 · Online state and device details <a class="header-anchor" href="#_03-·-online-state-and-device-details" aria-label="Permalink to &quot;03 · Online state and device details&quot;">​</a></h3><p>Track online, busy, paused, offline, and revoked states with last heartbeat, last sync, and current task. The device page shows capabilities, recent actions, and health checks. Expired heartbeats become offline, and offline devices receive no new desktop task.</p><h3 id="_04-·-revocation-task-ownership-and-audit" tabindex="-1">04 · Revocation, task ownership, and audit <a class="header-anchor" href="#_04-·-revocation-task-ownership-and-audit" aria-label="Permalink to &quot;04 · Revocation, task ownership, and audit&quot;">​</a></h3><p>Revocation invalidates sessions immediately, withdraws pending assignments, and moves running tasks to Needs attention. Audit pairing, capability calls, task association, and revocation. Acceptance proves undeclared windows are inaccessible, old sessions cannot be reused, and offline state is explicit.</p><h2 id="engineering-map" tabindex="-1">Engineering map <a class="header-anchor" href="#engineering-map" aria-label="Permalink to &quot;Engineering map&quot;">​</a></h2><h3 id="primary-directories-and-modules" tabindex="-1">Primary directories and modules <a class="header-anchor" href="#primary-directories-and-modules" aria-label="Permalink to &quot;Primary directories and modules&quot;">​</a></h3><ul><li><code>apps/agentd</code> — pairing, capability declaration, health checks, and revocation</li><li><code>packages/devices</code> — device identity, sessions, capability catalog, and online state</li><li><code>packages/desktop-observation</code> — window bounds, screenshots, accessibility tree, and redaction</li><li><code>packages/desktop-control</code> — allowlists, locators, input actions, and pre/postconditions</li><li><code>packages/desktop-verification</code> — screenshot comparison, focus checks, and half-complete detection</li><li><code>packages/approval</code> — desktop Effect Preview, second confirmation, and compensation guidance</li><li><code>apps/web</code> — device page, observation view, live takeover, and recovery</li></ul><h3 id="key-interfaces" tabindex="-1">Key interfaces <a class="header-anchor" href="#key-interfaces" aria-label="Permalink to &quot;Key interfaces&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Contract that must hold</th></tr></thead><tbody><tr><td><code>DeviceManifest</code></td><td>deviceId, publicKey, agentdVersion, capabilities, allowedRoots, expiresAt, revocationState; undeclared capabilities cannot be called.</td></tr><tr><td><code>ObservationFrame</code></td><td>captureId, windowBounds, screenshotRef, accessibilityTree, capturedAt, redactions; capture only the minimum scope required.</td></tr><tr><td><code>DesktopAction</code></td><td>actionType, targetWindow, locator, preconditions, expectedPostconditions, riskLevel, timeout; policy checks precede execution.</td></tr><tr><td><code>DesktopReceipt</code></td><td>actionId, beforeRef, afterRef, verification, partialState, compensation, approvalId; failure preserves recoverable evidence.</td></tr></tbody></table><h3 id="shared-verification-commands" tabindex="-1">Shared verification commands <a class="header-anchor" href="#shared-verification-commands" aria-label="Permalink to &quot;Shared verification commands&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:device:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pairing,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> capability</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> escalation,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> offline,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> revocation,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> session</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> expiry</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:desktop:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> observation,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> takeover,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> focus</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> changes,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> half-complete,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compensation</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:desktop-fault:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> window</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> drift,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vanished</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> elements,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> contention,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> crashes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:computer:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> at</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> least</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eight</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> real</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> desktop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tasks</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> and</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> failure</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> samples</span></span></code></pre></div><h2 id="acceptance-rehearsal" tabindex="-1">Acceptance rehearsal <a class="header-anchor" href="#acceptance-rehearsal" aria-label="Permalink to &quot;Acceptance rehearsal&quot;">​</a></h2><ol><li>Start hearthd from a clean data directory, open the <a href="/hearth-os/en/delivery/stage-3/d3-1.html">D3.1 page</a>, and confirm it relies on no browser cache or hand-seeded data.</li><li>Complete the four work packages in order: Device pairing and durable identity; Capability declaration and least privilege; Online state and device details; Revocation, task ownership, and audit. Preserve the matching test output, screenshot, or artifact version after each package.</li><li>Reproduce the failure case &quot;Window or element mismatch&quot;. The page must show &quot;The task pauses with the current screenshot and the element that needs confirmation.&quot;, then recover with &quot;Relocate, request takeover, or adjust the allowlist; never click coordinates blindly.&quot;; no duplicate effect or unregistered state is allowed.</li><li>Restart the service and reopen the task. Runtime state, approvals, artifacts, and recovery entry points must all come from durable projections rather than the current page.</li><li>Run the shared verification commands above and export the evidence. The completion gate is: A device registers, is visible, and can be revoked; mismatched tasks are not assigned; offline devices have explicit state; agentd cannot exceed declared capability.</li></ol><h2 id="deliverables" tabindex="-1">Deliverables <a class="header-anchor" href="#deliverables" aria-label="Permalink to &quot;Deliverables&quot;">​</a></h2><ul><li>Device pairing flow</li><li>Capability catalog and device detail</li><li>Disconnect/revoke demo</li><li>Undeclared-capability test</li></ul><h2 id="completion-decision" tabindex="-1">Completion decision <a class="header-anchor" href="#completion-decision" aria-label="Permalink to &quot;Completion decision&quot;">​</a></h2><ul><li>[ ] A device registers, is visible, and can be revoked; mismatched tasks are not assigned; offline devices have explicit state; agentd cannot exceed declared capability.</li><li>[ ] Deliverables match the contracts and task-card projection with no unregistered field or state.</li><li>[ ] At least one failure path has an actionable recovery, and key actions leave audit events.</li><li>[ ] The demo needs no manual database edit, terminal-only stitching, or permanent mock.</li></ul><h2 id="failure-and-recovery" tabindex="-1">Failure and recovery <a class="header-anchor" href="#failure-and-recovery" aria-label="Permalink to &quot;Failure and recovery&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case</th><th>User sees</th><th>Recovery</th></tr></thead><tbody><tr><td>Window or element mismatch</td><td>The task pauses with the current screenshot and the element that needs confirmation.</td><td>Relocate, request takeover, or adjust the allowlist; never click coordinates blindly.</td></tr><tr><td>Automatic input contends with the user</td><td>Automatic input pauses immediately and control goes to the user.</td><td>Wait for hand-back and confirm focus, window, and next step.</td></tr><tr><td>A high-risk action is half complete</td><td>The task shows Needs inspection, hides continue, and preserves the snapshot.</td><td>Recover with compensation or takeover and record the remaining impact.</td></tr></tbody></table><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>Do not automate when observation, verification, or takeover is unavailable.</li><li>Do not read password vaults, change system security settings, or operate unauthorized windows.</li><li>Do not treat one successful coordinate click as general GUI capability.</li></ul><h2 id="source-material-and-next-step" tabindex="-1">Source material and next step <a class="header-anchor" href="#source-material-and-next-step" aria-label="Permalink to &quot;Source material and next step&quot;">​</a></h2><h3 id="source-material" tabindex="-1">Source material <a class="header-anchor" href="#source-material" aria-label="Permalink to &quot;Source material&quot;">​</a></h3><ul><li><a href="/hearth-os/en/architecture/human-takeover.html">Human takeover and approval</a></li><li><a href="/hearth-os/en/architecture/execution-safety.html">Execution safety and effects</a></li><li><a href="/hearth-os/en/architecture/executor-catalog.html">Executor catalog</a></li><li><a href="/hearth-os/en/architecture/frontend-experience.html">Frontend and mobile experience</a></li></ul><h3 id="next-step" tabindex="-1">Next step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next step&quot;">​</a></h3><p>Continue to <a href="/hearth-os/en/delivery/stage-3/d3-2.html">D3.2 · GUI observation and human takeover</a>. Finish this increment&#39;s acceptance first; do not hide gaps with later work.</p>`,42)])])}const u=a(n,[["render",r]]);export{k as __pageData,u as default};
